INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório imediato de uma cirurgia abdominal, um paciente que vinha recebendo múltiplas transfusões de hemoderivados desenvolve agudamente edema pulmonar, hipertensão e turgência jugular. O balanço hídrico está fortemente positivo. Qual a principal suspeita diagnóstica relacionada à transfusão?", "options": {"a": "TRALI (Lesão Pulmonar Aguda Relacionada à Transfusão).", "b": "TACO (Sobrecarga Circulatória Associada à Transfusão).", "c": "Choque Séptico por sangue contaminado.", "d": "Anafilaxia ao plasma.", "e": "Embolia gasosa."}, "answer": "b", "rationale": "O TACO é essencialmente um edema pulmonar cardiogênico por excesso de volume transfundido, caracterizando-se por hipertensão e sinais de congestão (PVC alta, turgência).", "option_rationales": {"a": "Incorreta. TRALI costuma cursar com hipotensão ou normotensão e não há sinais de sobrecarga volêmica primária.", "b": "Correta. Diferencial importante no manejo de fluidos e hemoderivados.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Hematologia", "Pós-operatório", "Transfusão", "TACO"]}', 161, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Diferente do TACO, a TRALI (Transfusion-Related Acute Lung Injury) caracteriza-se fisiopatologicamente por:", "options": {"a": "Falência de bomba esquerda por infarto.", "b": "Aumento da permeabilidade capilar pulmonar devido à ativação de neutrófilos por anticorpos do doador.", "c": "Obstrução mecânica da artéria pulmonar.", "d": "Broncoespasmo severo reflexo.", "e": "Pneumonia bacteriana aspirativa precoce."}, "answer": "b", "rationale": "A TRALI é um tipo de SDRA imuno-mediada. Anticorpos no plasma do doador ativam os neutrófilos no pulmão do receptor, causando dano endotelial e edema não cardiogênico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Mecanismo de lesão endotelial imune.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Hematologia", "Pós-operatório", "TRALI", "Transfusão"]}', 162, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 55 anos, usuário crônico de prednisona (20 mg/dia) por artrite reumatoide, é submetido a uma gastrectomia. No 1º DPO, apresenta hipotensão refratária a volume e droga vasoativa, febre e náuseas. Laboratório mostra hiponatremia e hipercalemia. Qual a principal suspeita clínica?", "options": {"a": "Choque Séptico abdominal.", "b": "Insuficiência Adrenal Aguda (Crise Addisoniana pós-operatória).", "c": "Infarto agudo do miocárdio.", "d": "Fístula precoce de alto débito.", "e": "Reação transfusional tardia."}, "answer": "b", "rationale": "Pacientes em uso crônico de corticoides têm o eixo hipotálamo-hipófise-adrenal suprimido. O estresse cirúrgico exige um aumento da produção de cortisol que o organismo não consegue suprir, levando à crise adrenal.", "option_rationales": {"a": "Incorreta. Hipercalemia não é comum no choque séptico inicial (a menos que haja IRA grave).", "b": "Correta. Quadro clínico clássico de choque refratário e distúrbios eletrolíticos no usuário de corticoide.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Endocrinologia", "Pós-operatório", "Crise Adrenal", "Corticosteroides"]}', 163, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a medicação de escolha para o tratamento imediato da crise de Hipertermia Maligna durante a anestesia?", "options": {"a": "Dipirona venosa.", "b": "Dantrolene sódico.", "c": "Succinilcolina.", "d": "Atropina.", "e": "Propranolol."}, "answer": "b", "rationale": "O dantrolene é um relaxante muscular que age inibindo a liberação de cálcio do retículo sarcoplasmático, sendo a única droga eficaz para reverter o estado hipermetabólico da hipertermia maligna.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Antídoto específico salvador de vida.", "c": "Incorreta. Succinilcolina é um gatilho da doença.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Hipertermia Maligna", "Dantrolene"]}', 164, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a anestesia regional (bloqueio de plexo braquial) para cirurgia de punho desenvolve subitamente gosto metálico na boca, tontura, zumbido e evolui para convulsão tônico-clônica generalizada. Qual a complicação e a conduta imediata?", "options": {"a": "Epilepsia idiopática; Fenitoína.", "b": "Toxicidade Sistêmica por Anestésico Local (LAST); manutenção da via aérea e emulsão lipídica a 20% (Intralipid).", "c": "AVC hemorrágico; tomografia.", "d": "Crise de pânico; Diazepam.", "e": "Hipoglicemia grave; Glicose 50%."}, "answer": "b", "rationale": "A LAST ocorre pela absorção sistêmica rápida de anestésicos locais, atingindo o SNC e o sistema cardiovascular. O Intralipid age como um ''sorvedouro'' de lipídeos para retirar o anestésico da circulação livre.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Reconhecimento de toxicidade e tratamento específico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Anestesiologia", "Pós-operatório", "LAST", "Anestésico Local"]}', 165, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A cefaleia pós-punção dural (CPPD), complicação comum após raquianestesia ou punção acidental na peridural, tem como característica clínica principal:", "options": {"a": "Ser pior ao deitar e melhorar ao sentar.", "b": "Piora nítida na posição ortostática (em pé ou sentado) e alívio quase imediato ao decúbito dorsal plano.", "c": "Dor constante que não varia com a posição.", "d": "Associada a perda de visão súbita.", "e": "Dor apenas na região da nuca unilateral."}, "answer": "b", "rationale": "A dor é causada pela redução da pressão do LCR (hipotensão liquórica), que faz com que o cérebro ''tracione'' as meninges na posição vertical.", "option_rationales": {"a": "Incorreta. É o oposto.", "b": "Correta. Característica postural patognomônica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Cefaleia", "Raquianestesia"]}', 166, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 2º DPO de uma cirurgia de correção de aneurisma de aorta abdominal, o paciente apresenta diarreia com sangue, dor abdominal intensa e acidose metabólica. A tomografia mostra espessamento de parede de cólon esquerdo (sigmoide). Qual a complicação vascular provável?", "options": {"a": "Trombose venosa profunda.", "b": "Isquemia colônica aguda por ligadura ou baixo fluxo na artéria mesentérica inferior.", "c": "Apendicite aguda.", "d": "Diverticulite perfurada.", "e": "Colite por Clostridium dificille precoce."}, "answer": "b", "rationale": "A artéria mesentérica inferior é frequentemente clipada na cirurgia de aneurisma. Se a circulação colateral (Arco de Riolan) for insuficiente, ocorre isquemia colônica, tipicamente no cólon esquerdo.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação vascular específica da cirurgia aórtica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Muito precoce e a causa vascular é mais provável após o procedimento aórtico."}, "difficulty": "moderada", "tags": ["Cirurgia Vascular", "Pós-operatório", "Isquemia Colônica", "Aneurisma"]}', 167, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a tireoidectomia total desenvolve no pós-operatório imediato um hematoma cervical volumoso e expansivo, com sinais de estridor e dificuldade respiratória. Qual a conduta IMEDIATA de salvação de vida?", "options": {"a": "Encaminhar para Raio-x de pescoço.", "b": "Abertura imediata da ferida cirúrgica à beira do leito para descompressão local, seguida de revisão no centro cirúrgico.", "c": "Apenas administrar corticoides venosos.", "d": "Tentar intubação orotraqueal por 30 minutos sem abrir a ferida.", "e": "Colocar compressa de gelo."}, "answer": "b", "rationale": "O hematoma cervical causa compressão da via aérea e edema de glote. A descompressão manual (abrir os pontos) é o primeiro passo para permitir que o paciente respire enquanto se prepara a intubação ou reoperação.", "option_rationales": {"a": "Incorreta. Perda de tempo fatal.", "b": "Correta. Conduta de emergência clássica e salvadora.", "c": "Incorreta.", "d": "Incorreta. A via aérea estará desviada e edemaciada pela pressão externa, dificultando a intubação se não houver descompressão.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Hematoma Cervical", "Emergência"]}', 168, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de ''falência renal hepatorrenal'' no pós-operatório de pacientes cirróticos submetidos a cirurgias não-hepáticas?", "options": {"a": "Uso de antibióticos inofensivos.", "b": "Hipovolemia relativa (devido a ascite e vasodilatação esplâncnica) associada ao uso de diuréticos ou perdas sanguíneas não repostas adequadamente.", "c": "Excesso de sódio na dieta.", "d": "Consumo de proteínas exagerado.", "e": "Infeccção de pele distal."}, "answer": "b", "rationale": "O cirrótico já vive em um estado de circulação hiperdinâmica com vasodilatação sistêmica. Qualquer queda na volemia pode desencadear uma vasoconstrição renal intensa, levando à Síndrome Hepatorrenal.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fisiopatologia do insulto renal no cirrótico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Gastroenterologia", "Pós-operatório", "Cirrose", "Hepatorrenal"]}', 169, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A Síndrome do Compartimento Abdominal (SCA) é definida por uma Pressão Intra-abdominal (PIA) persistentemente acima de 20 mmHg associada a:", "options": {"a": "Icterícia e prurido.", "b": "Disfunção de novos órgãos (ex: queda do débito urinário, acidose ou hipoxemia).", "c": "Febre e leucocitose apenas.", "d": "Diarreia profusa.", "e": "Ganho de peso de 1 kg."}, "answer": "b", "rationale": "A HIA (Hipertensão Intra-abdominal) é baseada apenas no valor da pressão; a SCA exige a presença de falência orgânica causada por essa pressão elevada.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Definição diagnóstica de SCA (WSACS).", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "SCA", "Definição"]}', 170, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia colorretal desenvolve, no 5º DPO, dor abdominal súbita, desvios de septo e febre. O cirurgião suspeita de deiscência de anastomose. Qual o exame laboratorial de triagem que, se estiver NORMAL (< 50 mg/L), apresenta alto valor preditivo negativo para afastar complicações infecciosas graves neste período?", "options": {"a": "Leucograma.", "b": "Proteína C-Reativa (PCR).", "c": "Velocidade de Hemossedimentação (VHS).", "d": "Glicemia de jejum.", "e": "Creatinina sérica."}, "answer": "b", "rationale": "A PCR é um marcador de fase aguda muito sensível. No 3º-5º DPO, uma PCR baixa é um excelente preditor de ausência de deiscência de anastomose, auxiliando na alta segura.", "option_rationales": {"a": "Incorreta. Pode estar alterado por estresse cirúrgico ou uso de corticoides.", "b": "Correta. Utilidade clínica validada em protocolos ERAS para triagem de fístulas.", "c": "Incorreta. Muito lenta para variações agudas.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "PCR", "Triagem Infecciosa"]}', 171, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Na abordagem da sepse abdominal pós-operatória, qual a tríade de tratamento preconizada para o controle do foco (Source Control)?", "options": {"a": "Apenas antibióticos potentes.", "b": "Antibioticoterapia, suporte de órgãos e intervenção (cirúrgica ou percutânea) para drenagem e interrupção da contaminação.", "c": "Dieta parenteral e repouso no leito.", "d": "Corticoides, diuréticos e vasopressores.", "e": "Apenas observação rigorosa."}, "answer": "b", "rationale": "Não se trata sepse cirúrgica apenas com remédio. É necessário remover o pus (drenagem) e fechar o orifício de perfuração/fístula (controle do foco).", "option_rationales": {"a": "Incorreta. Erro comum; o antibiótico não penetra em abscessos volumosos.", "b": "Correta. Princípios do manejo da sepse cirúrgica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Sepse", "Controle do Foco"]}', 172, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a esternotomia mediana para revascularização desenvolve no 3º DPO quadro de dor abdominal intensa, distensão e vômitos. O dreno de tórax está normal. A amilase sérica é de 1.200 U/L. Qual complicação abdominal pode ocorrer após cirurgias com Circulação Extracorpórea (CEC)?", "options": {"a": "Pancreatite aguda (ischemia-reperfusão pancreática).", "b": "Cistite hemorrágica.", "c": "Flebite de veia cava.", "d": "Hernia diafragmática súbita.", "e": "Doença de Crohn aguda."}, "answer": "a", "rationale": "A CEC pode causar hipoperfusão sistêmica e microembolia, predispondo à isquemia de órgãos esplâncnicos, incluindo o pâncreas.", "option_rationales": {"a": "Correta. Complicação gastrointestinal reconhecida após cirurgia cardíaca complexa.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Pancreatite", "CEC"]}', 173, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação do uso crônico de dreno de tórax mantido por mais de 7 dias ou sem necessidade evidente?", "options": {"a": "Atrofia do pulmão.", "b": "Aumento do risco de infecção pleural (Empiema secundário).", "c": "Hipertensão portal.", "d": "Fratura de costela tardia.", "e": "Perda de cálcio pelos ossos."}, "answer": "b", "rationale": "O dreno é um corpo estranho que comunica o meio externo com a pleura. Quanto mais tempo permanece, maior a chance de colonização bacteriana e empiema.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Risco infeccioso proporcional ao tempo de permanência.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Torácica", "Pós-operatório", "Dreno de Tórax", "Empiema"]}', 174, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia abdominal desenvolve quadro de agitação psicomotora e, ao ser examinado, o médico nota tremor de mãos, taquicardia marcante e transpiração excessiva. O paciente confessa ser etilista pesado. Qual medicação deve ser prescrita profilaticamente para evitar a evolução para o Delirium Tremens?", "options": {"a": "Antipsicóticos apenas (Haloperidol).", "b": "Benzodiazepínicos (como Diazepam ou Lorazepam) em doses tituladas e reposição de Vitamina B1 (Tiamina).", "c": "Propranolol isolado.", "d": "Álcool via oral para o paciente.", "e": "Fenitoína."}, "answer": "b", "rationale": "A síndrome de abstinência alcoólica deve ser tratada com benzodiazepínicos, que têm tolerância cruzada com o álcool nos receptores GABA, prevenindo convulsões e delirium.", "option_rationales": {"a": "Incorreta. Podem baixar o limiar convulsivo.", "b": "Correta. Manejo padrão da abstinência alcoólica hospitalar.", "c": "Incorreta. Mascara a taquicardia sem tratar a causa neuroquímica.", "d": "Incorreta. Antiético e perigoso no ambiente hospitalar.", "e": "Incorreta. Não previne o delirium, apenas convulsões (e não é a droga de escolha)."}, "difficulty": "facil", "tags": ["Psiquiatria", "Pós-operatório", "Abstinência", "Alcoolismo"]}', 175, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A infecção urinária (ITU) no pós-operatório está associada quase exclusivamente a qual fator de risco?", "options": {"a": "Uso de antibiótico profilático.", "b": "Permanência de cateter vesical de demora (Sonda de Foley).", "c": "Tipo de anestesia realizada.", "d": "Posição de Trendelenburg.", "e": "Deambulação precoce."}, "answer": "b", "rationale": "Cerca de 80% das ITUs hospitalares estão relacionadas ao cateterismo vesical. A redução do tempo de sonda é a medida preventiva mais importante.", "option_rationales": {"a": "Incorreta. Na verdade previne, embora seu uso excessivo selecione germes resistentes.", "b": "Correta. Fator de risco número 1 para ITU pós-operatória.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Deambular ajuda a prevenir ITU ao facilitar o esvaziamento."}, "difficulty": "facil", "tags": ["Urologia", "Pós-operatório", "ITU", "Sondas"]}', 176, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação iatrogênica do uso de cateter de Swan-Ganz (cateter de artéria pulmonar) durante a monitorização hemodinâmica em cirurgia cardíaca?", "options": {"a": "Ruptura de artéria pulmonar.", "b": "Infarto esplênico.", "c": "Perfuração gástrica.", "d": "AVC isquêmico.", "e": "Lesão do nervo radial."}, "answer": "a", "rationale": "A migração inadvertida da ponta do cateter para um ramo distal e a insuflação do balonete podem causar a ruptura do vaso, levando a hemorragia pulmonar fulminante.", "option_rationales": {"a": "Correta. Complicação rara mas catastrófica da monitorização invasiva.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Terapia Intensiva", "Pós-operatório", "Monitorização Invasiva", "Swan-Ganz"]}', 177, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia oncológica de pelve desenvolve quadro de linfedema severo em membro inferior direito no 15º DPO. Qual a explicação anatômica?", "options": {"a": "Trombose venosa profunda obstrutiva.", "b": "Lesão ou ressecção extensa de cadeias linfáticas ilíacas e inguinais (Linfadenectomia) impedindo o retorno linfático.", "c": "Insuficiência cardíaca direita.", "d": "Falta de proteínas na dieta.", "e": "Celulite aguda."}, "answer": "b", "rationale": "O linfedema secundário é uma consequência comum da disrupção mecânica dos canais linfáticos durante cirurgias radicais oncológicas com esvaziamento ganglionar.", "option_rationales": {"a": "Incorreta. TVP dá edema venoso, não linfedema tipicamente (embora coexistam no diagnóstico diferencial).", "b": "Correta. Mecanismo direto pós-linfadenectomia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Oncologia", "Pós-operatório", "Linfedema", "Complicações"]}', 178, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cesariana, a paciente apresenta quadro de dor abdominal suprapúbica, febre, útero amolecido e doloroso à palpação, e loquios fétidos. Qual o diagnóstico?", "options": {"a": "Apendicite aguda.", "b": "Endometrite pós-parto.", "c": "Cistite.", "d": "Colecistite.", "e": "Deiscência da cicatriz abdominal apenas."}, "answer": "b", "rationale": "A endometrite é a complicação infecciosa mais comum após cesariana, caracterizada pela tríade de febre, dor uterina e loquios fétidos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Infecção de sítio cirúrgico ginecológico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Ginecologia e Obstetrícia", "Pós-operatório", "Endometrite"]}', 179, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual complicação de cicatrização caracteriza-se por uma proliferação excessiva de tecido fibroso (colágeno) que ultrapassa os limites da cicatriz original e não involui espontaneamente?", "options": {"a": "Cicatriz hipertrófica.", "b": "Queloide.", "c": "Seroma calcificado.", "d": "Fibromatose agressiva.", "e": "Granuloma de fio."}, "answer": "b", "rationale": "O queloide é um tumor benigno de colágeno que se estende além da margem da ferida, diferente da cicatriz hipertrófica que fica restrita à linha da incisão.", "option_rationales": {"a": "Incorreta. Fica restrita à linha da cicatriz.", "b": "Correta. Definição correta do queloide.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Plástica", "Pós-operatório", "Cicatrização", "Queloide"]}', 180, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia biliar vídeo-assistida apresenta no 4º DPO febre de 38,2°C e dor abdominal em hipocôndrio direito. O ultrassom mostra uma coleção líquida de 5 cm no leito vesicular (fossa cística). Qual a conduta inicial frente a este diagnóstico de abscesso ou coleção infectada?", "options": {"a": "Laparotomia exploradora imediata para nova cirurgia.", "b": "Drenagem percutânea orientada por imagem (USG ou Tomografia) e antibioticoterapia.", "c": "Tratamento apenas com analgésicos.", "d": "Uso de pomada antibiótica na pele.", "e": "Repetiçaõ da cirurgia por vídeo no mesmo dia."}, "answer": "b", "rationale": "Coleções intra-abdominais bloqueadas no pós-operatório devem ser tratadas preferencialmente por métodos minimamente invasivos (drenagem percutânea) para evitar uma nova reoperação agressiva em tecidos inflamados.", "option_rationales": {"a": "Incorreta. Muito invasivo como primeira linha.", "b": "Correta. Conduta padrão-ouro atual para abscessos localizados pós-op.", "c": "Incorreta.", "d": "Incorreta. Não trata foco profundo.", "e": "Incorreta. Drenagem percutânea é menos agressiva."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Abscesso", "Drenagem Percutânea"]}', 181, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente submetido a cirurgia sob anestesia geral desenvolve, após 24 horas, dor e edema em panturrilha direita. O médico solicita um Doppler. Qual marcador bioquímico, frequentemente usado para triagem de TEP no pronto-socorro, perde muito sua utilidade diagnóstica (baixo valor preditivo positivo) no pós-operatório imediato por estar elevado fisiologicamente?", "options": {"a": "Troponina.", "b": "D-Dímero.", "c": "Lactato.", "d": "Amilase.", "e": "Ureia."}, "answer": "b", "rationale": "O D-Dímero é um produto da degradação da fibrina. Como qualquer cirurgia envolve ativação da cascata de coagulação e formação/lise de fibrina, ele estará elevado em quase todos os pacientes cirúrgicos, perdendo especificidade para TEP/TVP.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Limitação clássica do D-Dímero no contexto cirúrgico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Pós-operatório", "TEP", "D-Dímero"]}', 182, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de ''pneumoperitônio'' visto no Raio-x de abdome em pé ou em decúbito lateral (Cúpula diafragmática) no 1º e 2º dia após uma laparotomia deve ser interpretada como:", "options": {"a": "Sinal de perfuração de víscera oca imediata.", "b": "Achado esperado por ar residual que entrou na cavidade durante a abertura cirúrgica e que demora alguns dias para ser reabsorvido.", "c": "Indicação de reoperação urgente.", "d": "Sinal de insuficiência hepática.", "e": "Obstrução intestinal."}, "answer": "b", "rationale": "É normal haver ar residual por até 5-7 dias após cirurgia aberta (mais curto em laparoscopias). O diagnóstico de perfuração exige correlação com sinais de peritonite e febre.", "option_rationales": {"a": "Incorreta. Pode ser ar residual.", "b": "Correta. Evolução radiológica normal do pós-op de laparotomia.", "c": "Incorreta. Sem clínica de peritonite, não se opera apenas o raio-x.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Pneumoperitônio", "Radiologia"]}', 183, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia de ressecção de tumor de canal anal com linfadenectomia inguinal, observa-se que o paciente apresenta drenagem persistente de líquido citrino pálido pela ferida inguinal, chegando a 300 ml/dia. Este quadro denomina-se:", "options": {"a": "Hematoma crônico.", "b": "Linfocisto ou fístula linfática.", "c": "ISC superficial.", "d": "Auscência de cicatrização.", "e": "Esvaziamento parcial."}, "answer": "b", "rationale": "A drenagem linfática abundante é frequente após esvaziamentos inguinais devido à rica rede de canais linfáticos da região. O tratamento pode envolver compressão local ou nova ligadura.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação específica de esvaziamentos linfonodais.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Oncologia", "Pós-operatório", "Linfocisto", "Inguinal"]}', 184, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de ''acidose lática'' no pós-operatório de pacientes submetidos a grandes cirurgias eletivas ou de trauma?", "options": {"a": "Excesso de insulina administrada.", "b": "Hipoperfusão tecidual (choque) levando ao metabolismo anaeróbio nas células.", "c": "Jejum de 8 horas.", "d": "Tosse produtiva.", "e": "Uso de anestésicos venosos."}, "answer": "b", "rationale": "O lactato é o marcador de sofrimento celular por falta de oferta de oxigênio (DO2). Sua elevação indica a necessidade de melhorar o débito cardíaco ou a volemia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Marcador de má perfusão e gravidade clínica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Terapia Intensiva", "Pós-operatório", "Acidose Lática", "Choque"]}', 185, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 3º DPO de uma esternotomia mediana para revascularização do miocárdio, o paciente apresenta agitação, taquicardia desproporcional à dor e queixa de dor intensa em panturrilha esquerda. O ECG mostra inversão de onda T de V1 a V4. Qual a conduta diagnóstica de escolha?", "options": {"a": "Angiotomografia de tórax (protocolo para TEP).", "b": "Apenas repetir Troponina.", "c": "Raio-x de tórax simples.", "d": "Gasometria arterial isolada.", "e": "Ultrassom de abdome."}, "answer": "a", "rationale": "A suspeita de TEP em um paciente de alto risco cirúrgico com alterações eletrocardiográficas e sintomas sugestivos deve ser confirmada por Angio-TC, sendo este o exame de escolha.", "option_rationales": {"a": "Correta. Padrão-ouro para diagnóstico de TEP.", "b": "Incorreta. Auxilia mas não confirma o evento embólico pulmonar.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "TEP", "Diagnóstico"]}', 186, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''seroma'' persistente após uma abdominoplastia estética é:", "options": {"a": "Uso de muita tela.", "b": "Grande espaço morto criado entre o retalho dermogorduroso e a aponeurose muscular, associado ao processo inflamatório local.", "c": "Infecção por micobactérias.", "d": "Alergia ao sabão do hospital.", "e": "Falta de uso de cinta elástica apenas."}, "answer": "b", "rationale": "A dissecção extensa rompe vasos linfáticos e cria um espaço onde o líquido pode se acumular. O uso de drenos e pontos de adesão (Pontos de Baroudi) tenta minimizar esse risco.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fisiopatologia do seroma em cirurgias de contorno corporal.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Embora a cinta ajude, o mecanismo é o espaço morto."}, "difficulty": "facil", "tags": ["Cirurgia Plástica", "Pós-operatório", "Seroma", "Abdominoplastia"]}', 187, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia biliar, o dreno apresenta saída de 500 ml de bile por dia. O paciente está bem, com icterícia em regressão. O cirurgião decide realizar uma colangiografia pelo dreno de Kehr. Se o exame mostrar que o contraste passa livremente para o duodeno, qual a conduta para o dreno?", "options": {"a": "Deve ser mantido aberto para sempre.", "b": "Pode ser fechado progressivamente e removido após cerca de 2 a 3 semanas (conforme o trajeto esteja maduro).", "c": "Reoperação para retirar o dreno.", "d": "Aumentar a pressão do dreno.", "e": "Uso de antibiótico profilático pelo dreno."}, "answer": "b", "rationale": "O dreno de Kehr (em T) deve permanecer tempo suficiente para que se forme um trajeto de fibrose ao seu redor (fístula madura), evitando que a bile extravase para o peritônio após sua retirada.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Manejo técnico do dreno de Kehr.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Dreno de Kehr", "Biliar"]}', 188, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação relacionada ao uso de ''grampeadores cirúrgicos'' lineares em anastomoses intestinais, especialmente quando há isquemia das bordas do tecido?", "options": {"a": "Câncer recidivante.", "b": "Fístula ou hemorragia na linha de grampeamento.", "c": "Aumento da motilidade intestinal.", "d": "Alergia ao titânio (extremamente raro).", "e": "Crescimento bacteriano excessivo."}, "answer": "b", "rationale": "Falhas no grampeamento ou tecidos friáveis/isquêmicos levam à deiscência (fístula) ou sangramento nos pontos de penetração dos grampos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Riscos mecânicos do uso de sutura mecânica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Sutura Mecânica", "Fístula"]}', 189, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia no 10º andar do hospital desenvolve no 3º DPO hipotensão, taquicardia e distensao de jugulares. O cirurgião diagnostica choque obstrutivo. Qual das opções abaixo pode causar este padrão hemodinâmico no pós-operatório?", "options": {"a": "Choque Séptico por pneumonia.", "b": "Choque Hipovolêmico por hemorragia.", "c": "Tromboembolismo Pulmonar maciço.", "d": "IAM com choque cardiogênico.", "e": "Sindrome do Intestino Curto."}, "answer": "c", "rationale": "O choque obstrutivo (TEP maciço, tamponamento cardíaco ou pneumotórax hipertensivo) caracteriza-se por turgência jugular (aumento da PVC) associada a hipotensão e baixo débito cardíaco por impedimento mecânico.", "option_rationales": {"a": "Incorreta. Distensao jugular não é comum no choque distributivo puro.", "b": "Incorreta. Jugulares estariam colabadas.", "c": "Correta. Causa frequente de choque obstrutivo pós-operatório.", "d": "Incorreta. Embora tenha turgência, o principal mecanismo é falha de bomba, mas o TEP é um diferencial clássico em pacientes cirúrgicos.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Pós-operatório", "Choque Obstrutivo", "TEP"]}', 190, 'draft')
